/** Approximate colour of a black body at the given effective temperature (display only). */
function teffColor(teff: number | null | undefined): string {
  const stops: [number, [number, number, number]][] = [
    [2400, [255, 128, 72]],
    [3500, [255, 172, 102]],
    [5000, [255, 220, 168]],
    [5800, [255, 244, 226]],
    [7500, [234, 240, 255]],
    [10000, [200, 216, 255]],
    [30000, [160, 188, 255]],
  ];
  const tk = teff && Number.isFinite(teff) ? teff : 5800;
  let c = stops[stops.length - 1]![1];
  for (let i = 0; i < stops.length - 1; i++) {
    const [t0, c0] = stops[i]!;
    const [t1, c1] = stops[i + 1]!;
    if (tk <= t0) {
      c = c0;
      break;
    }
    if (tk <= t1) {
      const f = (tk - t0) / (t1 - t0);
      c = [0, 1, 2].map((k) => Math.round(c0[k]! + (c1[k]! - c0[k]!) * f)) as [number, number, number];
      break;
    }
  }
  return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
}

function hashHue(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return Math.abs(h) % 360;
}

