function planetStyle(id: string, subclass: string, tags: string[] = [], profile = ''): CSSProperties {
  const key = (subclass + ' ' + tags.join(' ') + ' ' + id).toLowerCase();
  let hue = hashHue(id);
  let sat = 55;
  let light = 58;
  const tint = PROFILE_TINT[profile];
  if (tint) return { ['--lib-planet-h' as string]: tint[0], ['--lib-planet-s' as string]: tint[1] + '%', ['--lib-planet-l' as string]: tint[2] + '%' } as CSSProperties;
  if (/lava|hot|molten/.test(key)) [hue, sat, light] = [14, 85, 55];
  else if (/gas_giant|jupiter|saturn|giant/.test(key)) [hue, sat, light] = [32 + (hue % 18), 55, 66];
  else if (/ice|neptune|uranus|sub_neptune/.test(key)) [hue, sat, light] = [188 + (hue % 20), 60, 64];
  else if (/ocean|water/.test(key)) [hue, sat, light] = [205, 70, 56];
  else if (/desert|mars|rust/.test(key)) [hue, sat, light] = [18, 62, 52];
  else if (/earth|terrestrial|super_earth|rocky/.test(key)) [hue, sat, light] = [150 + (hue % 60), 45, 54];
  return { ['--lib-planet-h' as string]: hue, ['--lib-planet-s' as string]: sat + '%', ['--lib-planet-l' as string]: light + '%' } as CSSProperties;
}

function isLink(url: string): string | null {
  const m = /https?:\/\/[^\s)]+/.exec(url);
  return m ? m[0] : null;
}

// Lazy JSON records (detail views only).
const jsonCache = new Map<string, Promise<unknown>>();
function loadJson<T>(path: string): Promise<T> {
  let p = jsonCache.get(path);
  if (!p) {
    p = fetch(dataUrl(path, BASE)).then((r) => {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
    p.catch(() => jsonCache.delete(path));
    jsonCache.set(path, p);
  }
  return p as Promise<T>;
}
const sceneCache = new Map<string, Promise<SceneFile>>();
function loadSceneCached(id: string): Promise<SceneFile> {
  let p = sceneCache.get(id);
  if (!p) {
    p = loadScene(id, BASE);
    p.catch(() => sceneCache.delete(id));
    sceneCache.set(id, p);
  }
  return p;
}

function useAsync<T>(fn: () => Promise<T>, key: string): { data?: T; error?: unknown; retry: () => void } {
  const [state, setState] = useState<{ key: string; data?: T; error?: unknown }>({ key: '' });
  const [nonce, setNonce] = useState(0);
  useEffect(() => {
    let live = true;
    setState({ key });
    fn().then(
      (data) => live && setState({ key, data }),
      (error: unknown) => live && setState({ key, error }),
    );
    return () => {
      live = false;
    };
  }, [key, nonce]);
  return { data: state.key === key ? state.data : undefined, error: state.key === key ? state.error : undefined, retry: () => setNonce((n) => n + 1) };
}

