function StarDisc({ cls, teffK, size }: { cls: string; teffK: number | null; size: 'lg' | 'md' | 'sm' }) {
  const style = { ['--lib-star' as string]: teffColor(teffK) } as CSSProperties;
  return <span className={`lib-star lib-star--${size} lib-star--${cls}`} style={style} aria-hidden="true" />;
}

function WorldMini({ scene }: { scene: SceneIndexEntry }) {
  const m: SceneMiniature = scene.miniature;
  const rings = Math.min(m.planets, 6);
  const [primary, ...others] = m.stars;
  return (
    <div className={'lib-mini lib-mini--world lib-mini--' + scene.kind} aria-hidden="true">
      <div className="lib-mini__sky" />
      {Array.from({ length: rings }, (_, i) => {
        const r = 26 + ((i + 1) * 66) / rings; // % of the miniature width: outermost ring 92 %
        const angle = (((i * 137.5 + hashHue(scene.id)) % 360) * Math.PI) / 180;
        const style = {
          ['--r' as string]: r + '%',
          ['--x' as string]: (50 + 50 * Math.cos(angle)).toFixed(2) + '%',
          ['--y' as string]: (50 + 50 * Math.sin(angle)).toFixed(2) + '%',
          ...planetStyle(scene.id + i, ''),
        } as CSSProperties;
        return (
          <span key={i} className="lib-ring" style={style}>
            <span className="lib-ring__planet" />
          </span>
        );
      })}
      <div className="lib-mini__center">
        {primary ? <StarDisc cls={primary.cls} teffK={primary.teffK} size={m.stars.length > 1 ? 'md' : 'lg'} /> : <span className="lib-star lib-star--md lib-star--none" />}
        {others.map((s, i) => (
          <span key={i} className={'lib-companion lib-companion--' + i}>
            <StarDisc cls={s.cls} teffK={s.teffK} size="sm" />
          </span>
        ))}
      </div>
      {m.planets > rings && <span className="lib-mini__more">+{m.planets - rings}</span>}
    </div>
  );
}

function PresetMini({ preset }: { preset: PresetIndexEntry }) {
  if (preset.kind === 'system') {
    return (
      <div className="lib-mini lib-mini--preset lib-mini--system" aria-hidden="true">
        <span className="lib-binary">
          {preset.systemClasses.slice(0, 3).map((c, i) => (
            <span key={i} className={'lib-binary__b lib-binary__b--' + i}>
              <StarDisc cls={c} teffK={c === 'star' ? 5600 - i * 1800 : null} size="sm" />
            </span>
          ))}
        </span>
      </div>
    );
  }
  if (preset.kind === 'tool' || preset.kind === 'surface_config' || preset.kind === 'generator') {
    const icon = preset.kind === 'tool' ? 'target' : preset.kind === 'generator' ? 'sparkle' : 'layers';
    return (
      <div className={'lib-mini lib-mini--preset lib-mini--icon lib-mini--' + preset.kind} aria-hidden="true">
        <Icon name={icon} size={30} />
      </div>
    );
  }
  const b = preset.body;
  const cls = b?.cls ?? 'planet';
  return (
    <div className="lib-mini lib-mini--preset" aria-hidden="true">
      {cls === 'planet' || cls === 'moon' ? (
        <span className={'lib-planet lib-planet--' + cls + (b?.profile === 'Giant_Saturn' || /ring/.test(preset.tags.join(' ')) ? ' lib-planet--ringed' : '')} style={planetStyle(preset.id, b?.subclass ?? '', preset.tags, b?.profile)} />
      ) : (
        <StarDisc cls={cls} teffK={b?.teffK ?? null} size="md" />
      )}
    </div>
  );
}

