function Dialog({ title, onClose, children, lang }: { title: string; onClose: () => void; children: ReactNode; lang: Lang }) {
  const ref = useRef<HTMLDivElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    const prev = document.activeElement as HTMLElement | null;
    closeRef.current?.focus();
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
      }
      if (e.key === 'Tab' && ref.current) {
        const f = Array.from(ref.current.querySelectorAll<HTMLElement>('a[href], button:not([disabled]), input, select, [tabindex]:not([tabindex="-1"])'));
        if (!f.length) return;
        const first = f[0]!;
        const last = f[f.length - 1]!;
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault();
          last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };
    document.addEventListener('keydown', onKey);
    const overflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.removeEventListener('keydown', onKey);
      document.body.style.overflow = overflow;
      prev?.focus?.();
    };
  }, [onClose]);
  return (
    <div className="lib-dialog" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className="lib-dialog__panel" role="dialog" aria-modal="true" aria-label={title} ref={ref}>
        <button type="button" className="lib-dialog__close" onClick={onClose} ref={closeRef} aria-label={U.close[lang]}>
          <Icon name="close" size={18} />
        </button>
        {children}
      </div>
    </div>
  );
}

