function BodyRow({ b, lang, units, optional }: { b: SceneBody; lang: Lang; units: 'astro' | 'si'; optional?: boolean }) {
  const unc = b.uncertainty?.mass_kg;
  let pm = '';
  if (Array.isArray(unc) && unc.length === 2 && b.mass_kg > 0) {
    const rel = ((Math.abs(Number(unc[0])) + Math.abs(Number(unc[1]))) / 2 / b.mass_kg) * 100;
    if (Number.isFinite(rel) && rel > 0) pm = ' ± ' + formatNumber(rel, lang, 2) + ' %';
  }
  const el = (b as SceneBody & { elements?: { a_m?: number; period_s?: number } }).elements;
  const prov = b.provenance?.mass_kg?.kind;
  const flags = b.flags ?? {};
  return (
    <tr>
      <th scope="row">
        <span className="lib-body-name">{t(b.name, lang)}</span>
        <span className="lib-body-flags">
          {optional && <span className="lib-flag">{tr('flag.optional', lang)}</span>}
          {flags.msini && <span className="lib-flag lib-flag--warn" title={tr('flag.msini.tip', lang)}>m sin i</span>}
          {flags.candidate && <span className="lib-flag">{tr('flag.candidate', lang)}</span>}
          {flags.controversial && <span className="lib-flag lib-flag--warn">{tr('flag.controversial', lang)}</span>}
          {flags.conditional && <span className="lib-flag">{tr('flag.conditional', lang)}</span>}
        </span>
      </th>
      <td>
        {classLabel(b.class, lang)}
        {b.subclass && <span className="lib-faint"> · {classLabel(b.subclass, lang, 'subclass')}</span>}
      </td>
      <td className="lib-num">
        {formatQuantity('mass', b.mass_kg, lang, units, 4)}
        {pm && <span className="lib-faint">{pm}</span>}
      </td>
      <td className="lib-num">{b.radius_m > 0 ? formatQuantity('radius', b.radius_m, lang, units, 4) : '—'}</td>
      <td className="lib-num">
        {el?.a_m ? formatQuantity('distance', el.a_m, lang, units, 3) : '—'}
        {el?.period_s ? <span className="lib-faint"> · {formatSpan(el.period_s, lang)}</span> : null}
      </td>
      <td>{prov ? <span className={'lib-prov-pill lib-prov--' + prov}>{tr('prov.' + prov, lang)}</span> : '—'}</td>
    </tr>
  );
}

