function WorldsTab({ lang, focus }: { lang: Lang; focus?: string }) {
  const [q, setQ] = useState('');
  const [kind, setKind] = useState<string>('all');
  const list = useMemo(() => {
    let rows = INDEX.scenes;
    if (q.trim()) {
      const order = new Map(searchCatalog(INDEX, q, undefined, 500).filter((h) => h.type === 'scene').map((h, i) => [h.id, i]));
      rows = rows.filter((s) => order.has(s.id)).sort((a, b) => order.get(a.id)! - order.get(b.id)!);
    } else {
      rows = [...rows].sort((a, b) => SCENE_KIND_ORDER.indexOf(a.kind) - SCENE_KIND_ORDER.indexOf(b.kind));
    }
    return kind === 'all' ? rows : rows.filter((s) => s.kind === kind);
  }, [q, kind]);
  const options = [
    { id: 'all', label: U.all[lang], count: INDEX.scenes.length },
    ...SCENE_KIND_ORDER.map((k) => ({ id: k, label: t(INDEX.labels.sceneKinds[k], lang), count: INDEX.scenes.filter((s) => s.kind === k).length })),
  ];
  const open = focus ? sceneById.get(focus) : undefined;
  return (
    <>
      <div className="lib-toolbar">
        <SearchBox value={q} onChange={setQ} placeholder={U.searchWorlds[lang]} label={U.search[lang] + ': ' + U.worlds[lang]} />
        <Chips label={U.kind[lang]} value={kind} options={options} onChange={setKind} />
        <div className="lib-count" aria-live="polite">
          {fill(U.shown[lang], { n: list.length, total: INDEX.scenes.length })}
        </div>
      </div>
      {focus && !open && <NotFound id={focus} lang={lang} />}
      {list.length ? (
        <div className="lib-grid lib-grid--worlds">
          {list.map((s) => (
            <WorldCard key={s.id} s={s} lang={lang} />
          ))}
        </div>
      ) : (
        <Empty lang={lang} onClear={() => (setQ(''), setKind('all'))} />
      )}
      {open && <WorldDetail s={open} lang={lang} onClose={() => navigate('/library/worlds')} />}
    </>
  );
}

