type LearningItem = { type: 'lesson'; entry: LessonIndexEntry } | { type: 'experiment'; entry: ExperimentIndexEntry };

interface QuestionRecord {
  id: string;
  text?: LocalizedText;
  choices?: { id: string; text?: LocalizedText }[];
  correct?: string;
}

/** A self-check question: pick an answer, then reveal the correct one (nothing is graded or recorded). */
function SelfCheck({ q, lang }: { q: QuestionRecord; lang: Lang }) {
  const [picked, setPicked] = useState<string | null>(null);
  const [shown, setShown] = useState(false);
  return (
    <fieldset className="lib-quiz">
      <legend>{t(q.text, lang)}</legend>
      <div className="lib-quiz__choices">
        {(q.choices ?? []).map((c) => {
          const state = shown ? (c.id === q.correct ? ' is-correct' : c.id === picked ? ' is-wrong' : '') : '';
          return (
            <label key={c.id} className={'lib-quiz__choice' + (picked === c.id ? ' is-picked' : '') + state}>
              <input type="radio" name={'lib-q-' + q.id} value={c.id} checked={picked === c.id} onChange={() => setPicked(c.id)} />
              <span>{t(c.text, lang)}</span>
            </label>
          );
        })}
      </div>
      {q.correct && (
        <button type="button" className="lib-btn lib-btn--ghost lib-btn--sm" onClick={() => setShown((v) => !v)} aria-expanded={shown}>
          {shown ? U.hideAnswer[lang] : U.showAnswer[lang]}
        </button>
      )}
    </fieldset>
  );
}

